"""Read exact request/criteria and source excerpts for an independent caller review.

This is evidence preparation, not a semantic consistency or art-acceptance verdict.
"""

import re
from hashlib import sha256
from pathlib import Path
from typing import Any

from . import graph, plar


def source_evidence(root, source, expected, budget=16384):
    """Resolve explicit lines or legacy numbered prose against this file only."""
    local = graph.confined(root, source["path"])
    result = {
        "path": source["path"],
        "sha256": expected,
        "locator": source.get("locator"),
        "absolute_path": str(local),
    }
    if not local.is_file():
        return {**result, "status": "missing"}
    if local.stat().st_size > 64 * 1024 * 1024:
        return {**result, "status": "too_large"}
    data = local.read_bytes()
    actual = sha256(data).hexdigest()
    result.update(observed_sha256=actual)
    if actual != expected:
        return {**result, "status": "changed"}
    try:
        lines = data.decode("utf-8-sig").splitlines(keepends=True)
    except UnicodeError:
        return {
            **result,
            "status": "visual_source",
            "instruction": "Inspect the actual referenced artifact through the host.",
        }
    result["line_count"] = len(lines)
    explicit = source.get("lines")
    if explicit is not None:
        if (
            not isinstance(explicit, list)
            or len(explicit) != 2
            or any(type(n) is not int for n in explicit)
        ):
            return {
                **result,
                "status": "invalid_locator",
                "reason": "lines must be [first, last] integer bounds",
            }
        ranges = [explicit]
    else:
        ranges = [
            [int(a), int(b or a)]
            for a, b in re.findall(
                r"\blines?\s+(\d+)(?:\s*[-–]\s*(\d+))?",
                source.get("locator", ""),
                re.IGNORECASE,
            )
        ]
    if not ranges:
        return {
            **result,
            "status": "unresolved_locator",
            "instruction": "Use file-local lines [first,last] or inspect the named source location; no locator is assumed verified.",
        }
    if any(not 1 <= start <= end <= len(lines) for start, end in ranges):
        return {
            **result,
            "status": "invalid_locator",
            "requested_lines": ranges,
            "reason": f"Source has {len(lines)} lines; one or more bounds are outside it.",
        }
    excerpts: list[dict[str, Any]] = [
        {"lines": [start, end], "text": "".join(lines[start - 1 : end])}
        for start, end in ranges
    ]
    if sum(len(item["text"].encode("utf-8")) for item in excerpts) > budget:
        return {**result, "status": "needs_narrower_range", "requested_lines": ranges}
    return {
        **result,
        "status": "resolved",
        "excerpts": excerpts,
        "scope": "Exact cited text only; its meaning and support for the criterion need caller comparison.",
    }


def report(root, packet_path, asset_id=None, path="plar.txt", plan=None, job=None, comparison=None, view="complete", against_plan=None):
    if view not in ("complete", "changes"):
        raise graph.PixlError("request_review", "view must be complete or changes")
    if view == "changes":
        if plan is None or against_plan is None:
            raise graph.PixlError("request_review", "changes view requires plan and against_plan")
        from . import successor_review

        return successor_review.report(root, packet_path, plan, against_plan, job, comparison)
    if against_plan is not None:
        raise graph.PixlError("request_review", "against_plan requires changes view")
    if plan is not None:
        from . import production_review

        return production_review.report(root, packet_path, plan, job, comparison)
    if job is not None or comparison is not None:
        raise graph.PixlError("request_review", "job/comparison require a connected plan")
    from jsonschema import Draft202012Validator

    from .plar_prepare import SCHEMA, _artifact, _json_file, _require

    root = Path(root).resolve()
    packet, digest, packet_path = _json_file(root, packet_path)
    _require(
        type(packet.get("version")) is int and packet["version"] == 1,
        "expected request-review version 1",
    )
    _require(isinstance(packet.get("sources"), list), "packet sources must be a list")
    sources: dict[str, dict[str, Any]] = {}
    for source in packet["sources"]:
        _require(
            isinstance(source, dict) and {"path", "sha256", "role"} <= source.keys(),
            "packet sources need path, sha256 and role",
        )
        name = graph.confined(root, source["path"]).relative_to(root).as_posix()
        _require(
            name not in sources or sources[name]["sha256"] == source["sha256"],
            "conflicting source identities",
        )
        sources[name] = source
    pointer = packet.get("request")
    _require(
        isinstance(pointer, dict) and pointer.get("kind") == "provider_arguments",
        "review expects exact provider arguments, not a creative brief",
    )
    request, request_hash, request_path = _artifact(root, packet.get("request"))
    connection = None
    if "connection" in pointer:
        value, connection_hash, connection_path = _artifact(root, pointer["connection"])
        connection = {
            "path": connection_path,
            "sha256": connection_hash,
            "provider": value.get("provider"),
            "discovery": value.get("discovery"),
            "authorization": value.get("authorization"),
        }

    plan, plan_hash, plan_path = _artifact(root, packet.get("criteria"))
    error = next(Draft202012Validator(SCHEMA).iter_errors(plan), None)
    _require(error is None, f"candidate plan: {error.message if error else ''}")
    evidence, comparisons, diagnostics = [], [], []
    if (
        connection
        and "provider" in pointer
        and pointer["provider"] != connection["provider"]
    ):
        diagnostics.append(
            {
                "status": "provider_mismatch",
                "packet": pointer["provider"],
                "connection": connection["provider"],
            }
        )

    source_bindings = []
    for source in packet["sources"]:
        local = graph.confined(root, source["path"])
        name = local.relative_to(root).as_posix()
        observed = (
            graph.file_hash(local)
            if local.is_file() and local.stat().st_size <= 64 * 1024 * 1024
            else None
        )
        status = (
            "current"
            if observed == source["sha256"]
            else "changed"
            if observed is not None
            else "unavailable"
        )
        source_bindings.append(
            {**source, "observed_sha256": observed, "binding": status}
        )
        if status != "current":
            diagnostics.append({"source": name, "status": status})
        pointers = [source] if "locator" in source or "lines" in source else []
        locators = source.get("locators", [])
        if isinstance(locators, list) and all(
            isinstance(value, str) for value in locators
        ):
            pointers.extend({**source, "locator": value} for value in locators)
        else:
            diagnostics.append(
                {"packet_source": name, "status": "unresolved_locator_format"}
            )
        for citation in pointers:
            item = source_evidence(root, citation, source["sha256"])
            if item not in evidence:
                evidence.append(item)
            source_bindings[-1].setdefault("source_evidence", []).append(
                evidence.index(item)
            )
            if item["status"] != "resolved":
                diagnostics.append(
                    {
                        "packet_source": name,
                        "locator": citation.get("locator"),
                        "status": item["status"],
                    }
                )

    for output in plan["outputs"]:
        for criterion in output["criteria"]:
            indices = []
            for source in criterion["sources"]:
                name = graph.confined(root, source["path"]).relative_to(root).as_posix()
                _require(
                    name in sources, f"criterion source absent from packet: {name}"
                )
                item = source_evidence(root, source, sources[name]["sha256"])
                if item not in evidence:
                    evidence.append(item)
                index = evidence.index(item)
                indices.append(index)
                if item["status"] != "resolved":
                    diagnostics.append(
                        {
                            "output": output["id"],
                            "criterion": criterion["id"],
                            "source": index,
                            "status": item["status"],
                        }
                    )
            comparisons.append(
                {
                    "output": output["id"],
                    **criterion,
                    "source_evidence": indices,
                    "comparison": "unperformed",
                }
            )
    selected = plar.read(root, path, asset_id) if asset_id else None
    if selected and packet.get("requirements_hash") != selected["requirements_hash"]:
        diagnostics.append(
            {
                "status": "changed_selection",
                "packet": packet.get("requirements_hash"),
                "current": selected["requirements_hash"],
            }
        )
    return {
        "version": 1,
        "packet": {"path": packet_path, "sha256": digest},
        "request": {
            "path": request_path,
            "sha256": request_hash,
            "tool": packet["request"].get("tool"),
            "provider": pointer.get("provider"),
            "provider_simulated_assertion": pointer.get("provider_simulated"),
            "connection": connection,
            "arguments": request,
        },
        "criteria": {
            "path": plan_path,
            "sha256": plan_hash,
            "scope": plan["scope"],
            "comparisons": comparisons,
        },
        "candidate_controls": [
            {"output": o["id"], "contract": o["contract"]} for o in plan["outputs"]
        ],
        "sources": source_bindings,
        "choices": packet.get("choices", []),
        "source_evidence": evidence,
        "diagnostics": diagnostics,
        "production": selected.get("production") if selected else None,
        "caller_comparison": "unperformed",
        "consistent": None,
        "scope": "Read-only exact evidence. Resolved lines do not establish semantic entailment, contract consistency, execution or asset acceptance.",
    }

"""PX2 intake, planned outputs, candidate acceptance and read-only readiness.

The graph module owns wire/schema, reference, file and evidence-hash validation.
This module runs after those checks. Reports consume an already validated graph
and never create evidence, advance tasks or recursively invoke validation.
"""

from datetime import datetime

from .codec import PixlError, encode_value, to_data

NONRASTER = {"code", "report", "reference"}
CONTRACT_FIELDS = {"nm", "px", "pl", "vw", "sa", "al", "li", "ch", "tg"}
ADOPTION_PHASES = {"production", "delivery"}


def _require(condition, code, detail):
    if not condition:
        raise PixlError(code, detail)


def _ids(references):
    return {reference.id for reference in references}


def _unique(references, code, detail):
    _require(len(_ids(references)) == len(references), code, detail)


def _output_choices(doc, task):
    """Only output contracts impose a task's own project/style obligations.

    A source input may intentionally belong to another project or contract.
    Unrelated project choices also do not gate research or accepted samples.
    """
    choices = set()
    for output in task["op"]:
        contract = doc.records[output.id].fields.get("ct")
        if contract is not None:
            choices.update(_ids(doc.records[contract.id].fields.get("ch", [])))
    return choices


def _activation_blockers(doc, task_id, scope, bound):
    from . import families

    task = doc.records[task_id].fields
    reasons = []
    for dependency in task["dp"]:
        state = doc.records[dependency.id].fields["st"].value
        if state != "done":
            reasons.append(f"task_prerequisite: {dependency.id} is {state}; it must be done")
    for reference in task["op"]:
        output = doc.records[reference.id].fields
        if output["kd"].value not in NONRASTER and "ct" not in output:
            reasons.append(f"output_contract: {reference.id} needs a concrete raster contract")
    choice_ids = sorted(_output_choices(doc, task))
    for choice_id in choice_ids:
        choice = doc.records[choice_id].fields
        state = choice["st"].value
        if state in {"unresolved", "conflict"}:
            reasons.append(
                f"choice_{state}: {choice_id} ({choice['ky']}) is {state}; resolve it before active work"
            )
    if task["ph"].value in ADOPTION_PHASES:
        if not task["dc"]:
            reasons.append(f"task_decision: {task_id} needs an evidence-backed adoption decision")
        for reference in task["kn"]:
            method = doc.records[reference.id].fields
            if not scope(reference.id) <= bound(method.get("pc", []), passing=True):
                reasons.append(f"method_poc: {reference.id} needs current passing method proof")
        for choice_id in choice_ids:
            choice = doc.records[choice_id].fields
            if choice["st"].value in {"observed", "proposed"}:
                reasons.append(f"choice_unconfirmed: {choice_id} ({choice['ky']}) must be confirmed")
    reasons.extend(families.blockers(doc, task_id))
    return reasons


def validate(doc, scope, bound):
    """Validate PX2 semantics after the graph's shared checks.

    ``scope(id)`` returns the semantic proof closure. ``bound(refs, passing)``
    returns IDs bound by current receipts. Both are supplied by graph.validate
    so lifecycle checks use precisely the same evidence interpretation.
    """
    choice_keys = set()
    current_verdicts = {}

    for id_, record in doc.records.items():
        f = record.fields
        if record.kind == "P":
            _unique(f["in"], "intake_project", f"{id_}.in repeats a choice")
            for choice in f["in"]:
                _require(
                    doc.records[choice.id].fields["pr"].id == id_,
                    "intake_project", f"{id_}.in includes another project's choice {choice.id}",
                )
        elif record.kind == "I":
            project_id = f["pr"].id
            _require(
                id_ in _ids(doc.records[project_id].fields["in"]),
                "intake_project", f"{id_} must be listed in {project_id}.in",
            )
            choice_key = (project_id, f["ky"])
            _require(
                bool(f["ky"].strip()) and choice_key not in choice_keys,
                "intake_key", f"{id_}: choice keys must be nonempty and unique within a project",
            )
            choice_keys.add(choice_key)
            state, value = f["st"].value, f["vl"]
            if state == "unresolved":
                _require(value is None, "intake_value", f"{id_}: unresolved value must be null")
            elif state == "conflict":
                _require(
                    isinstance(value, list) and len(value) >= 2,
                    "intake_value", f"{id_}: conflict needs at least two alternatives",
                )
            else:
                _require(value is not None, "intake_value", f"{id_}: {state} value cannot be null")
            if state in {"observed", "confirmed"}:
                _require(bool(f["so"]), "intake_source", f"{id_}: {state} choice needs sources")
            if state == "proposed":
                _require(bool(f["wy"].strip()), "intake_rationale", f"{id_}: proposal needs a rationale")
        elif record.kind == "C":
            _unique(f.get("ch", []), "contract_choice", f"{id_}.ch repeats a choice")
            for reference in f.get("ch", []):
                choice = doc.records[reference.id].fields
                # Retain the last interpretation while an open/blocked task
                # resolves changed intent. Activation is gated separately.
                if choice["st"].value in {"unresolved", "conflict"}:
                    continue
                key = choice["ky"]
                if key in CONTRACT_FIELDS:
                    _require(
                        key in f and encode_value(choice["vl"]) == encode_value(f[key]),
                        "contract_choice", f"{id_}.{key} does not equal choice {reference.id}",
                    )
        elif record.kind == "F":
            owner = doc.records[f["tk"].id].fields
            _require(id_ in _ids(owner["op"]), "output_owner", f"{id_} must be listed by its owning task")
            _require(bool(f["rq"]), "output_requirements", f"{id_} needs at least one acceptance criterion")
            _unique(f["rq"], "output_requirements", f"{id_}.rq repeats a criterion")
        elif record.kind == "Q":
            _require(bool(f["ck"].strip()), "criterion_check", f"{id_} needs an observable check")
            required_mode = {"visual": "visual", "engine": "live"}.get(f["dm"].value)
            _require(
                required_mode is None or f["md"].value == required_mode,
                "criterion_mode", f"{id_}: {f['dm'].value} requires {required_mode} evidence",
            )
        elif record.kind == "X":
            _require(
                f["kd"].value in NONRASTER or "ct" in f,
                "artifact_contract", f"{id_}: a materialized raster needs a contract",
            )
            if "of" in f:
                output = doc.records[f["of"].id].fields
                _require(
                    f["kd"] == output["kd"] and f.get("ct") == output.get("ct"),
                    "candidate_output", f"{id_} must match its planned output's kind and contract",

